import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"사용자 가이드","description":"","frontmatter":{},"headers":[],"relativePath":"ko-KR/user-guide/index.md","filePath":"ko-KR/user-guide/index.md","lastUpdated":1788366161000}'),s={name:"ko-KR/user-guide/index.md"};function l(i,e,n,d,c,g){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="사용자-가이드" tabindex="-1">사용자 가이드 <a class="header-anchor" href="#사용자-가이드" aria-label="Permalink to &quot;사용자 가이드&quot;">​</a></h1><p>Lertaro 공식 사용자 가이드에 오신 것을 환영합니다! Lertaro는 Windows 환경에 최적화된 초고속 파일 검색기 및 생산성 런처입니다. 백그라운드에서 고성능 인메모리 인덱스 트리(NTFS / ReFS는 USN 변경 저널, 기타 파일 시스템은 실시간 이벤트 감지)를 유지하여 수천만 개의 파일에서도 밀리초 미만의 검색 반응 속도를 제공합니다.</p><p>본 가이드에서는 일상 업무에 필요한 기본 사용법부터 고급 기능까지 체계적으로 설명합니다.</p><ul><li><strong><a href="./getting-started.html">빠른 시작</a></strong> —— 설치 및 포터블 버전 사용법, App과 Service 아키텍처 역할, 3가지 윈도우 모드(퀵 / 메인 / 인라인) 및 기본 조작.</li><li><strong><a href="./search-syntax.html">검색 문법</a></strong> —— 퍼지 매칭, 연산자(<code>!</code> 제외, <code>&#39;</code> 완전 일치, <code>^</code> 접두사, <code>$</code> 접미사, <code>|</code> OR 조건), 드라이브 지정, 경로 모드 및 한어병음 별칭.</li><li><strong><a href="./hotkeys.html">단축키 및 제스처</a></strong> —— 전역 단축키 요약표, 검색창 로고 마우스 드래그/리셋 제스처, 마우스 퀵 내비게이션 계단식 메뉴 및 핵심 고정 키.</li><li><strong><a href="./actions-and-preview.html">액션 및 미리보기</a></strong> —— 컨텍스트 액션 패널(<code>Ctrl+O</code>), 메인 윈도우 결과 목록 조작, QuickLook 미디어/문서 미리보기 및 플러그인 인터랙티브 카드.</li><li><strong><a href="./space-analyzer.html">공간 분석</a></strong> —— 디스크 I/O 제로의 초고속 트리맵 차트 및 크기 내림차순 목록으로 대용량 파일 정리.</li><li><strong><a href="./instant-answers.html">인스턴트 답변 및 키워드 기능</a></strong> —— 상시 활성화된 계산기, 환경 변수, 명령 실행 및 프로세스 관리(<code>ps</code>), 창 전환(<code>win</code>), 브라우저 북마크(<code>bb</code>), 브라우저 방문 기록(<code>bh</code>), 설정 검색(<code>set</code>) 등의 플러그인.</li><li><strong><a href="./cli.html">명령줄 검색 (lff)</a></strong> —— 터미널용 대화형 퍼지 검색 도구로, 메모리 인덱스를 공유하여 파이프라인 및 쉘 스크립트와 연동.</li><li><strong><a href="./uri-protocol.html">URI 프로토콜 (lertaro://)</a></strong> —— 웹 링크, 바로가기, 스크립트에서 검색창, 설정 페이지, LocalSend 전송으로 즉시 이동.</li><li><strong><a href="./file-manager-support.html">지원 파일 관리자</a></strong> —— Windows 표준 대화상자 및 Directory Opus, Total Commander, XYplorer, Files 등과의 임베드 및 내비게이션 연동.</li><li><strong><a href="./settings/">설정 항목 참조</a></strong> —— 서비스 상태, 인덱싱 관리, 일반 설정, 모양, 단축키, 플러그인 설정의 전 항목 상세 설명.</li><li><strong><a href="./troubleshooting.html">문제 해결</a></strong> —— 전역 단축키 먹통, 인덱스 미갱신, 입력기 후보창 문제 진단 및 실시간 로그 확인.</li><li><strong><a href="./donate.html">후원 및 기부</a></strong> —— Lertaro의 지속적인 개발 및 오픈소스 유지보수 후원.</li></ul><div class="tip custom-block github-alert"><p class="custom-block-title">TIP</p><p>Lertaro를 처음 사용하시는 경우 먼저 <a href="./getting-started.html"><strong>빠른 시작</strong></a>을 읽어보시는 것을 추천합니다.</p></div>',5)])])}const m=t(s,[["render",l]]);export{p as __pageData,m as default};
